DROP VIEW IF EXISTS `Sales_vStoreWithContacts`;
CREATE VIEW `Sales_vStoreWithContacts` AS
select `s`.`BusinessEntityID` AS `BusinessEntityID`,`s`.`Name` AS `Name`,`ct`.`Name` AS `ContactType`,`p`.`Title` AS `Title`,`p`.`FirstName` AS `FirstName`,`p`.`MiddleName` AS `MiddleName`,`p`.`LastName` AS `LastName`,`p`.`Suffix` AS `Suffix`,`pp`.`PhoneNumber` AS `PhoneNumber`,`pnt`.`Name` AS `PhoneNumberType`,`ea`.`EmailAddress` AS `EmailAddress`,`p`.`EmailPromotion` AS `EmailPromotion` from ((((((`adventureworks`.`Sales_Store` `s` join `adventureworks`.`Person_BusinessEntityContact` `bec` on((`bec`.`BusinessEntityID` = `s`.`BusinessEntityID`))) join `adventureworks`.`Person_ContactType` `ct` on((`ct`.`ContactTypeID` = `bec`.`ContactTypeID`))) join `adventureworks`.`Person_Person` `p` on((`p`.`BusinessEntityID` = `bec`.`PersonID`))) left join `adventureworks`.`Person_EmailAddress` `ea` on((`ea`.`BusinessEntityID` = `p`.`BusinessEntityID`))) left join `adventureworks`.`Person_PersonPhone` `pp` on((`pp`.`BusinessEntityID` = `p`.`BusinessEntityID`))) left join `adventureworks`.`Person_PhoneNumberType` `pnt` on((`pnt`.`PhoneNumberTypeID` = `pp`.`PhoneNumberTypeID`)))